                )
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            if (boundDate == currentBoundDate) {
                _uiState.update { it.copy(isLoading = false, errorMessage = friendlyError(e, localizer)) }
            }
        }
    }
}

private fun observeSubmitState() {
    submitStateJob?.cancel()
    val uid = repository.currentUserId().orEmpty()
    val boundDate = currentBoundDate
    submitStateJob = viewModelScope.launch {
        reportSubmitManager.stateForMission(campaignId, missionId, uid, boundDate).collect { state ->
            if (boundDate != currentBoundDate) return@collect
            _uiState.update { it.copy(submitState = state) }
            if (state?.stage == ReportSubmitManager.Stage.DONE) {
                if (uid.isNotBlank() && MissionReportDraftStore.loadDraft(appContext, uid, campaignId, missionId, boundDate) == null) {
                    savedStateHandle.remove<String>(draftKey(uid, "comment", boundDate))
                    savedStateHandle.remove<Int>(draftKey(uid, "rating", boundDate))
                }
                loadData()
            }
        }
    }
}

fun updateRating(newRating: Int) {
    checkAndRefreshDay()
    userEditRevision++
    val clamped = newRating.coerceIn(1, 5)
    val uid = repository.currentUserId().orEmpty()
    savedStateHandle[draftKey(uid, "rating", currentBoundDate)] = clamped

