-- 076_mission_for_finalized_campaigns.sql
-- Extend create_mission, join_mission, resume_mission, and _submit_tester_report_core
-- to allow finalized campaigns ('production' and 'completed') in addition to 'open'.
-- Normal testing submission ('app_test') remains strictly 'open' only.

-- 1. create_mission
