            'mission_id', p_mission_id,
            'status', 'expired'
        );
    end if;

    -- Khóa campaign row
    select * into v_camp
    from public.campaigns
    where id = v_mission.campaign_id
    for update;

    if v_camp.id is null then
        raise exception 'CAMPAIGN_NOT_FOUND';
    end if;
    if v_camp.status not in ('open', 'production', 'completed') then
